record ServerConfig(String host, int port, Duration timeout, boolean tls) {
    static final ServerConfig DEFAULT =
        new ServerConfig("localhost", 8080, Duration.ofSeconds(30), false);
    ServerConfig withPort(int p) { return new ServerConfig(host, p, timeout, tls); }
    ServerConfig withTls(boolean t) { return new ServerConfig(host, port, timeout, t); }
}

var secure = ServerConfig.DEFAULT.withPort(9000).withTls(true);
